import{_ as t,C as i,o as r,c as l,E as o,a2 as s}from"./chunks/framework.BOeh4kYD.js";const _=JSON.parse('{"title":"重放曾经成功，不等于仍有执行资格","description":"","frontmatter":{"title":"重放曾经成功，不等于仍有执行资格","date":"2026-09-17","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"当一个数字员工曾经成功执行过一条可复用记忆时，下一次重放需要哪些新鲜证据，才能证明它仍然适用于当前状态、仍获业务授权，并且其外部效果可以被安全核对？","summary":"可执行记忆能显著降低重复任务成本，但历史成功只产生重放候选。每次运行仍须重新证明兼容性、业务授权与外部效果，三者不能由相似度或旧轨迹替代。","sources":["research/analysis/Q-20260917-01-replay-eligibility-is-a-fresh-execution-time-fact.md"],"item_id":"Q-20260917-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-17-successful-replay-not-standing-execution-right-cover-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-09-17-successful-replay-not-standing-execution-right.md","filePath":"zh/digital-employee/2026-09-17-successful-replay-not-standing-execution-right.md","lastUpdated":1789665186000}'),n={name:"zh/digital-employee/2026-09-17-successful-replay-not-standing-execution-right.md"};function p(c,e,h,d,u,g){const a=i("ArticleCover");return r(),l("div",null,[o(a,{image:"/assets/covers/daily-2026-09-17-successful-replay-not-standing-execution-right-cover-v2.webp",kicker:"数字员工 · 每日研究",title:"重放曾经成功，不等于仍有执行资格",summary:"可执行记忆能显著降低重复任务成本，但历史成功只产生重放候选。每次运行仍须重新证明兼容性、业务授权与外部效果，三者不能由相似度或旧轨迹替代。",version:"Q-20260917-01",status:"Daily Runtime V5 · 2026-09-17",languageHref:"/en/digital-employee/2026-09-17-successful-replay-not-standing-execution-right",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="重放曾经成功-不等于仍有执行资格" tabindex="-1">重放曾经成功，不等于仍有执行资格 <a class="header-anchor" href="#重放曾经成功-不等于仍有执行资格" aria-label="Permalink to &quot;重放曾经成功，不等于仍有执行资格&quot;">​</a></h1><p>一条操作记忆昨天成功完成了任务，今天又遇到相似请求。检索系统给出高相似度，运行时于是准备直接重放。这个决定看似节省成本，却把三个不同问题压成了一个：这条记忆在当前环境里还能不能运行、当前主体现在有没有权力运行、运行之后怎样证明外部效果正确。</p><p>历史成功很有价值。它可以把一次昂贵探索变成可复用能力。但成功轨迹不是永久通行证。工具版本、页面结构、账户状态、目标资源和授权都可能变化；一次超时还可能已经产生副作用。真正可靠的重放，需要把候选发现、执行资格、业务授权与效果核对分别保存。</p><h2 id="重放值得保留-因为它确实降低重复成本" tabindex="-1">重放值得保留，因为它确实降低重复成本 <a class="header-anchor" href="#重放值得保留-因为它确实降低重复成本" aria-label="Permalink to &quot;重放值得保留，因为它确实降低重复成本&quot;">​</a></h2><p>同日研究对象分析 EchoPath（可验证可执行记忆系统）的可执行记忆实验。论文报告，在145个与第一遍匹配的第二遍任务上，系统完成率为91.2%，与对照方法91.8%接近；但中位令牌用量约20,370，而对照方法约586,386，中位时间约127.5秒，而对照方法约315.7秒。</p><p>这些数字支持一个有用结论：把成功轨迹提炼成可执行记忆，确实可能降低重复求解的成本。工程系统不应因为治理困难就放弃复用。</p><p>但这里证明的是复用价值，不是永久资格。完成率来自论文的受控任务与定义，不能自动外推到所有工具、账户和有副作用操作。</p><h2 id="相似-只能找到候选" tabindex="-1">相似，只能找到候选 <a class="header-anchor" href="#相似-只能找到候选" aria-label="Permalink to &quot;相似，只能找到候选&quot;">​</a></h2><p>论文还报告一项检索压力测试：记忆库从159条扩展到659条时，召回率保持100%。这说明检索机制可以在更大的候选集合中找回正确记忆。</p><p>召回回答的是“哪条记忆可能相关”。它不回答“这条记忆现在能否安全运行”。两个请求可以在语义上高度相似，却指向不同账户、不同预算、不同地理范围或已经升级的工具模式。</p><p>因此，相似度应止步于候选层。它可以触发后续检查，却不能直接生成执行许可。把检索分数接到工具调用上，相当于让文本相似性替代当前事实。</p><h2 id="执行资格必须在本次运行重新证明" tabindex="-1">执行资格必须在本次运行重新证明 <a class="header-anchor" href="#执行资格必须在本次运行重新证明" aria-label="Permalink to &quot;执行资格必须在本次运行重新证明&quot;">​</a></h2><p>EchoPath 的准入机制检查生命周期、制品、推理、动作模式、状态和灵活输入等条件。研究对象报告，状态门禁接受了49个兼容和46个部分兼容案例，拒绝39个不兼容案例；对可替换字段的50次变化全部接受，对不可替换字段的50次变化全部拒绝。</p><p>这些结果支持一种更严格的设计：资格是执行时事实。运行时必须重新绑定精确记忆版本、工具或页面模式、所需状态、允许替换的输入以及当前任务边界。</p><p>“部分兼容”也不应被翻译为静默成功。它需要明确哪些差异仍被规则允许、哪些字段必须由新请求提供、哪些变化会使记忆失效。若系统无法证明，正确状态不是猜测，而是拒绝或转人工路径。</p><h2 id="一条可审计重放链需要六种身份" tabindex="-1">一条可审计重放链需要六种身份 <a class="header-anchor" href="#一条可审计重放链需要六种身份" aria-label="Permalink to &quot;一条可审计重放链需要六种身份&quot;">​</a></h2><p>最小重放记录至少要把六种身份连在一起：</p><ul><li><strong>请求身份</strong>：谁提出了什么目标，面向哪个资源；</li><li><strong>记忆身份</strong>：采用哪个版本的可执行记忆，来源于哪次成功；</li><li><strong>动作身份</strong>：调用哪个工具模式与参数结构；</li><li><strong>状态身份</strong>：检查了哪个时间点的环境快照；</li><li><strong>授权身份</strong>：哪个策略版本允许哪个主体为哪个目的执行；</li><li><strong>效果身份</strong>：用什么业务键确认外部变化。</li></ul><p>这些字段不是为了堆日志，而是为了回答失败后的关键问题。若工具模式升级，可以定位哪些记忆需要失效；若权限被撤销，可以证明后续重放是否使用了新决定；若出现重复副作用，可以用效果身份核对而不是盲目再次调用。</p><h2 id="兼容通过-仍可能没有业务授权" tabindex="-1">兼容通过，仍可能没有业务授权 <a class="header-anchor" href="#兼容通过-仍可能没有业务授权" aria-label="Permalink to &quot;兼容通过，仍可能没有业务授权&quot;">​</a></h2><p>研究中的重放门禁主要证明技术适配：制品仍可用、状态满足前置条件、动作模式匹配、输入变化在允许范围内。它没有建立企业业务授权。</p><p>业务授权必须另行回答：当前主体是谁、目的是什么、允许哪些操作、额度多大、有效到何时、目标资源是否在范围内。一个技术上完全可重放的付款流程，仍可能因为额度变化、账户冻结或审批撤销而不得执行。</p><p>权限还必须绑定本次动作，而不是仅绑定记忆。记忆是程序性材料，不是权力来源。即使同一人创建过这条记忆，也不能假定未来每个使用者都继承原始权限。</p><h2 id="调用成功-也不能证明效果只发生一次" tabindex="-1">调用成功，也不能证明效果只发生一次 <a class="header-anchor" href="#调用成功-也不能证明效果只发生一次" aria-label="Permalink to &quot;调用成功，也不能证明效果只发生一次&quot;">​</a></h2><p>工具返回成功，只能证明接口给出了某种响应。网络超时可能发生在外部系统已经写入之后；重试可能制造第二次效果；返回成功也可能不满足业务后置条件。</p><p>因此，效果核对应独立于调用结果。对有副作用操作，运行时至少要保存业务幂等键、预期效果、外部资源版本和核对结果。若效果未知，应先读取外部事实，再决定重试、补偿或人工处理。</p><p>这一步也是历史轨迹无法代替的。旧轨迹能示范如何调用，却不能证明这一次订单、账户或资源已经进入正确状态。</p><h2 id="一份最小重放合同" tabindex="-1">一份最小重放合同 <a class="header-anchor" href="#一份最小重放合同" aria-label="Permalink to &quot;一份最小重放合同&quot;">​</a></h2><p>一个实用的最小合同可以按五步执行：</p><ol><li>以相似度和结构约束检索候选，但不授予执行权；</li><li>对精确记忆版本、动作模式、当前状态和输入替换重新做资格判断；</li><li>对主体、目的、范围、额度、时效和目标资源获得新鲜授权；</li><li>使用效果身份与幂等或补偿策略执行；</li><li>核对外部事实，并把成功、失败或未知写入证据包。</li></ol><p>任何关键事实缺失，都应保留为未知或失败关闭。重放可以更快，但不能通过删除检查来获得速度。</p><h2 id="边界与开放问题" tabindex="-1">边界与开放问题 <a class="header-anchor" href="#边界与开放问题" aria-label="Permalink to &quot;边界与开放问题&quot;">​</a></h2><p>现有证据来自图形界面任务与论文定义的评估环境。它没有建立企业授权正确性、恰好一次副作用、隐私边界或跨组织撤销传播。本文提出的合同是从这些结果推导的架构原则，不是论文直接验证的生产保证。</p><p>仍待回答的问题包括：不同风险等级需要多新鲜的状态快照；工具模式变化到什么程度必须废弃旧记忆；权限撤销如何及时传播到缓存；并发重放怎样共享业务幂等键；哪些效果可以自动核对，哪些必须由负责主体确认。</p><p>有界结论是：<strong>历史成功值得复用，但每一次执行资格都必须在当下重新证明。重放准入、业务授权和效果验证必须保持为三条独立、可审计的证据链。</strong></p><p><strong>证据与来源：</strong></p><ul><li><a href="https://arxiv.org/abs/2609.16635" target="_blank" rel="noreferrer">EchoPath：面向长时程计算机使用智能体的可验证可执行记忆</a>，2026。</li></ul>',37))])}const f=t(n,[["render",p]]);export{_ as __pageData,f as default};
